@Throws(Exception::class)
suspend fun analyzeContent(
    bookSource: BookSource,
    book: Book,
    bookChapter: BookChapter,
    baseUrl: String,
    redirectUrl: String,
    body: String?,
    nextChapterUrl: String?,
    needSave: Boolean = true
): String {
    body ?: throw NoStackTraceException(
        appCtx.getString(R.string.error_get_web_content, baseUrl)
    )
    Debug.log(bookSource.bookSourceUrl, "≡获取成功:${baseUrl}")
    Debug.log(bookSource.bookSourceUrl, body, state = 40)
    val mNextChapterUrl = if (nextChapterUrl.isNullOrEmpty()) {
        appDb.bookChapterDao.getChapter(book.bookUrl, bookChapter.index + 1)?.url
            ?: appDb.bookChapterDao.getChapter(book.bookUrl, 0)?.url
    } else {
        nextChapterUrl
    }
    val contentList = arrayListOf<String>()
    val nextUrlList = arrayListOf(redirectUrl)
    val contentRule = bookSource.getContentRule()
    val analyzeRule = AnalyzeRule(book, bookSource)
    analyzeRule.setContent(body, baseUrl)
    analyzeRule.setRedirectUrl(redirectUrl)
    analyzeRule.setCoroutineContext(currentCoroutineContext())
    analyzeRule.setChapter(bookChapter)
    analyzeRule.setNextChapterUrl(mNextChapterUrl)
    currentCoroutineContext().ensureActive()
    var contentData = analyzeContent(
        book, baseUrl, redirectUrl, body, contentRule, bookChapter, bookSource, mNextChapterUrl
    )
    contentList.add(contentData.first)
    if (contentData.second.size == 1) {
        val webJs = contentRule.webJs
        var nextUrl = contentData.second[0]
        while (nextUrl.isNotEmpty() && !nextUrlList.contains(nextUrl)) {
            if (!mNextChapterUrl.isNullOrEmpty()
                && NetworkUtils.getAbsoluteURL(redirectUrl, nextUrl)
                == NetworkUtils.getAbsoluteURL(redirectUrl, mNextChapterUrl)
            ) break
            nextUrlList.add(nextUrl)
            currentCoroutineContext().ensureActive()

    return text
        .replace("\\r\\n", "\n")
        .replace("\\n", "\n")
        .replace("\\r", "\n")
}

fun format(html: String?, otherRegex: Regex = otherHtmlRegex): String {
    return formatText(html, otherRegex, "　　")
}

fun formatIntro(html: String?): String {
    return formatText(html, otherHtmlRegex, "")
}

private fun formatText(html: String?, otherRegex: Regex, paragraphIndent: String): String {
    html ?: return ""
    return normalizeEscapedLineBreaks(html)
        .replace(nbspRegex, " ")
        .replace(espRegex, " ")
        .replace(noPrintRegex, "")
        .replace(wrapHtmlRegex, "\n")
        .replace(commentRegex, "")
        .replace(otherRegex, "")
        .replace(indent1Regex, "\n$paragraphIndent")
        .replace(indent2Regex, paragraphIndent)
        .replace(lastRegex, "")
}

